package com.github.yutaplug.profileboard

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.Base64

/** Transparent still of the Nitro Wishlist mascot. */
internal object NitroArtwork {
    private val parts = arrayOf(
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    )
    private var cached: Bitmap? = null

    fun bitmap(): Bitmap? {
        cached?.let { return it }
        val encoded = StringBuilder()
        var index = 0
        while (index < parts.size) {
            encoded.append(parts[index])
            index++
        }
        val bytes = Base64.decode(encoded.toString(), Base64.NO_WRAP)
        return BitmapFactory.decodeByteArray(bytes, 0, bytes.size)?.also { cached = it }
    }
}
